CREATE TABLE IF NOT EXISTS representantes(rep_id BIGSERIAL PRIMARY KEY,cli_id BIGINT NOT NULL,per_id BIGINT NOT NULL,rep_per_id BIGINT NOT NULL,rep_tip VARCHAR(30) NOT NULL,rep_fec_des DATE,rep_fec_has DATE,rep_pri BOOLEAN NOT NULL DEFAULT FALSE,rep_obs VARCHAR(500),rep_usu_mov VARCHAR(50) NOT NULL,rep_fec_mov TIMESTAMP NOT NULL,rep_act BOOLEAN NOT NULL DEFAULT TRUE);
CREATE INDEX IF NOT EXISTS idx_representantes_persona ON representantes(cli_id,per_id,rep_act);
CREATE TABLE IF NOT EXISTS domicilios_notificacion(don_id BIGSERIAL PRIMARY KEY,cli_id BIGINT NOT NULL,per_id BIGINT NOT NULL,dom_id BIGINT NOT NULL,don_tip VARCHAR(30) NOT NULL,don_fec_des DATE,don_fec_has DATE,don_pri BOOLEAN NOT NULL DEFAULT FALSE,don_obs VARCHAR(500),don_usu_mov VARCHAR(50) NOT NULL,don_fec_mov TIMESTAMP NOT NULL,don_act BOOLEAN NOT NULL DEFAULT TRUE);
CREATE INDEX IF NOT EXISTS idx_domicilios_notificacion_persona ON domicilios_notificacion(cli_id,per_id,don_act);
CREATE TABLE IF NOT EXISTS domiciliaciones_bancarias(dob_id BIGSERIAL PRIMARY KEY,cli_id BIGINT NOT NULL,per_id BIGINT NOT NULL,dob_tip VARCHAR(10) NOT NULL CHECK(dob_tip IN('CARGO','ABONO')),dob_tit VARCHAR(150) NOT NULL,dob_iban_cif VARCHAR(500) NOT NULL,dob_bic VARCHAR(20),dob_ref_man VARCHAR(100),dob_fec_man DATE,dob_pri BOOLEAN NOT NULL DEFAULT FALSE,dob_est VARCHAR(20) NOT NULL CHECK(dob_est IN('ACTIVA','INACTIVA')),dob_usu_mov VARCHAR(50) NOT NULL,dob_fec_mov TIMESTAMP NOT NULL,dob_act BOOLEAN NOT NULL DEFAULT TRUE);
CREATE INDEX IF NOT EXISTS idx_domiciliaciones_bancarias_persona ON domiciliaciones_bancarias(cli_id,per_id,dob_act);
